const timeInfo = await Aboutme.system.getCurrentTime();
const today = `${timeInfo.year}-${String(timeInfo.month).padStart(2, '0')}-${String(timeInfo.day).padStart(2, '0')}`;
const result = await Aboutme.plugins.activity.getActivities({ date: today, offset: 10, count: 10 });
