const timeInfo = await Aboutme.system.getCurrentTime();
const today = `${timeInfo.year}-${String(timeInfo.month).padStart(2, '0')}-${String(timeInfo.day).padStart(2, '0')}`;
let allActivities = [];
let offset = 0;
const count = 20;

while (true) {
  const result = await Aboutme.plugins.activity.getActivities({ date: today, offset, count });
  allActivities = allActivities.concat(result.data);

  if (!result.hasMore) break;
  offset += count;
}

setResult(`共加载 ${allActivities.length} 个活动`);

const baseTime = await Aboutme.system.getCustomDate({relativePosition: 'startOfDay', format: 'iso'});
const startTime = baseTime.replace(/T.*/, 'T08:00:00.000Z');
const endTime = baseTime.replace(/T.*/, 'T10:00:00.000Z');
const result = await Aboutme.plugins.activity.createActivity({
  startTime,
  endTime,
  title: '晨间会议'
});
setResult(result.success ? '创建成功' : '创建失败');

